import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import crypto from 'node:crypto';
import ts from 'typescript';

const repository=fs.realpathSync('.');
const parent=fs.realpathSync('.git');
if(parent!==path.join(repository,'.git'))throw new Error('Unexpected probe parent');
const sandbox=fs.mkdtempSync(path.join(parent,'b04-scratch-lifecycle-'));
const cases=[
 ['src/infrastructure/parsers/integration.test.ts','afterAll','SCRATCHPAD'],
 ['src/infrastructure/sources/integration.test.ts','beforeAll','TEST_DIR'],
 ['src/infrastructure/hooks/settings-manager.test.ts','beforeEach','testBaseDir'],
 ['src/infrastructure/hooks/hook-runner.test.ts','beforeEach','testDir'],
];
const observations=[];
for(const [file,hook,binding] of cases) {
 const source=fs.readFileSync(file,'utf8');
 const ast=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true);
 let callback;
 const visit=node=>{
  if(!callback && ts.isCallExpression(node) && node.expression.getText(ast)===hook) callback=node.arguments[0];
  ts.forEachChild(node,visit);
 };
 visit(ast);
 if(!callback || !ts.isArrowFunction(callback))throw new Error('Missing callback '+file);
 const extracted=callback.getText(ast);
 const js=ts.transpileModule('('+extracted+')()',{
  compilerOptions:{target:ts.ScriptTarget.ESNext,module:ts.ModuleKind.ESNext}
 }).outputText;
 const caseRoot=fs.mkdtempSync(path.join(sandbox,'case-'));
 const target=path.join(caseRoot,'existing-scratch');
 fs.mkdirSync(target);
 const marker=path.join(target,'preexisting-synthetic-marker.txt');
 fs.writeFileSync(marker,'Owned by the probe, preexisting relative to the extracted test callback.',{flag:'wx'});
 const checked=p=>{
  const absolute=path.resolve(p);
  if(!absolute.startsWith(caseRoot+path.sep))throw new Error('Probe boundary escape');
  let ancestor=absolute;
  while(ancestor!==caseRoot) {
   if(fs.existsSync(ancestor) && fs.lstatSync(ancestor).isSymbolicLink())throw new Error('Probe link');
   ancestor=path.dirname(ancestor);
  }
  return absolute;
 };
 const removals=[];
 vm.runInNewContext(js,{
  [binding]:target,
  MOCK_CLAUDE_DIR:path.join(target,'.claude','projects'),
  join:path.join,
  existsSync:p=>fs.existsSync(checked(p)),
  mkdirSync:(p,options)=>fs.mkdirSync(checked(p),options),
  writeFileSync:(p,data,...options)=>fs.writeFileSync(checked(p),data,...options),
  rmSync:(p,options)=>{const absolute=checked(p);removals.push(path.relative(caseRoot,absolute));fs.rmSync(absolute,options);},
 },{timeout:2000});
 observations.push({file,hook,sourceHash:crypto.createHash('sha256').update(source.replaceAll('\r\n','\n')).digest('hex'),
  callback:extracted,markerSurvived:fs.existsSync(marker),removals});
}
console.log(JSON.stringify({kind:'Extracted lifecycle callback diagnostic; not passing regressions',
 sandbox:path.relative(repository,sandbox),observations,
 limits:'Only freshly allocated project .git probe directories were mutated. No original test module, production memory, existing scratch directory, browser, provider or full test runner was invoked. Retained artifacts are synthetic.'},null,2));

